from collections import deque

def shortest_path_length(graph):
    n = len(graph)
    full = (1 << n) - 1
    q = deque((i, 1 << i, 0) for i in range(n))
    seen = {(i, 1 << i) for i in range(n)}
    while q:
        u, m, d = q.popleft()
        if m == full:
            return d
        for v in graph[u]:
            st = (v, m | 1 << v)
            if st not in seen:
                seen.add(st)
                q.append((v, st[1], d + 1))
    return 0

