int shortestPathLength(vector<vector<int>>& g) {
    int n = g.size(), full = (1 << n) - 1; vector<vector<char>> seen(n, vector<char>(1 << n, 0)); deque<array<int,3>> q;
    for (int i = 0; i < n; i++) { q.push_back({i, 1 << i, 0}); seen[i][1 << i] = 1; }
    while (!q.empty()) { auto [u, m, d] = q.front(); q.pop_front(); if (m == full) return d; for (int v : g[u]) { int nm = m | 1 << v; if (!seen[v][nm]) { seen[v][nm] = 1; q.push_back({v, nm, d + 1}); } } }
    return 0;
}
